- اللەھقە يالغان چاپلىغان ياكى (ئۇنى) ئىنكار قىلغان كىشىدىن زالىم كىم بار؟ (وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ) 6:21; 6:93; 7:37; 10:17; 29:68
- بىر ئىشنى ھۆكۈم قىلغاندا، ئۇنىڭغا پەقەت «بوپقال» دەيدۇ-دە، ئۇ دەرھال بوپقالىدۇ. (وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 2:117; 3:47; 19:35; 40:68
- ۋە اللەھتىن باشقا سىلەرگە ھېچقانداق ئىگە ۋە ياردەمچى يوق. (وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 9:116; 29:22; 42:31
- مەن ئۇلارنىڭ گۇناھلىرىنى چوقۇم ئۆچۈرىمەن ۋە ئۇلارنى ئاستىدىن ئۆستەڭلار ئېقىپ تۇرىدىغان جەننەتلەرگە كىرگۈزىمەن. (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- ئۇلارنى ئاستىدىن ئۆستەڭلار ئېقىپ تۇرىدىغان جەننەتلەرگە كىرگۈزىمىز، ئۇلار ئۇنىڭدا مەڭگۈ قالىدۇ. (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- پەرۋەردىگارىڭ ئۇنىڭ يولىدىن ئازغان كىشىلەرنى ئوبدان بىلىدۇ ۋە ئۇ ئۆزى ئوبدان بىلىدۇ. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- سىلەر غەيب ۋە شاھىدنى بىلگۈچىگە قايتۇرۇلىسىلەر، ئاندىن ئۇ سىلەرگە قىلىۋاتقان ئىشلىرىڭلارنى خەۋەر قىلىدۇ. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- ئوغۇللىرىڭلارنى ئۆلتۈرۈپ، ئاياللىرىڭلارنى تىرىك قالدۇراتتى؛ بۇنىڭدا سىلەرگە پەرۋەردىگارىڭلاردىن ئۇلۇغ سىناق بار ئىدى. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- شەك-شۈبھىسىزكى، پەرۋەردىگارىڭ ئۇنىڭ يولىدىن ئازغان كىشىلەرنى ئوبدان بىلىدۇ ۋە ئۇ. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- اللەھ، ئاسمانلاردىكى ۋە زېمىندىكى نەرسىلەر ئۇنىڭ ئىگىلىكىدە. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- سىلەردىن ئىلگىرى ئۆتكەن ئۈممەتلەر ئىچىدە – جىن ۋە ئىنسانلاردىن. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- اللەھقە ئىبادەت قىلىڭلار، سىلەرگە ئۇنىڭدىن باشقا ھېچ ئىلاھ يوق. قورقمايسىلەرمۇ؟ (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- ئۇلارنىڭ ئۇنى چۈشىنىپ يەتمەسلىكى ئۈچۈن قەلبلىرىگە پەردىلەر، قۇلاقلىرىغا ئېغىرلىق قويدۇق. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- قىيامەت كۈنى ئۇلارنىڭ ئىختىلاپ قىلىۋاتقان نەرسىلىرىدە (اللەھ) ئۇلارنىڭ ئارىسىدا ھۆكۈم چىقىرىدۇ. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- ئۇ دېدى: «ئى قەۋمىم! ئەگەر مەن پەرۋەردىگارىمدىن ئېنىق پاكىت ئۈستىدە بولسام، سىلەر نېمە دەيسىلەر؟» (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- بۇ، قوللىرىڭلارنىڭ ئىلگىرى ئەۋەتكەن (ئەمەللىرى) سەۋەبىدىندۇر؛ اللەھ بەندىلەرگە زۇلۇم قىلغۇچى ئەمەس. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- دۇنيادا ئۇلارغا خارلىق، ئاخىرەتتە ئۇلارغا ئۇلۇغ ئازاب بار. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- ئاسمانلاردىكى ۋە زېمىندىكى نەرسىلەر؛ اللەھ ۋەكىل بولۇشقا يېتەرلىك. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- پەقەت ئىمان كەلتۈرگەن ۋە ياخشى ئەمەللەرنى قىلغان كىشىلەر بۇنىڭ سىرتىدا؛ ئۇلارغا ئۈزۈلمەيدىغان ئەجىر بار. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- ماڭا شېرىك كەلتۈرۈشۈڭ ئۈچۈن – ئۇنىڭ توغرىسىدا ھېچقانداق ئىلىمىڭ يوق؛ ئۇ ئىككىسىگە ئىتائەت قىلما. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- شەك-شۈبھىسىزكى، بۇ بىر ۋەز-نەسىھەتتۇر؛ خالىغان كىشى پەرۋەردىگارىغا تارتىدىغان يولنى تاللىسۇن. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- كىم شۈكۈر قىلسا، پەقەت ئۆزىنىڭ پايدىسى ئۈچۈن شۈكۈر قىلىدۇ؛ كىم كۇفرى نېمەت قىلسا، شەك-شۈبھىسىز. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- ئۇلار نامازنى تىك تۇتۇپ، زاكات بېرىپ، ئاخىرەتكە يەقىن قىلىدۇ. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ئىبراھىم، ئىسمائىل، ئىسھاق، يەئقۇب ۋە ئەۋلادلىرى؛ مۇسا ۋە ئىساغا بېرىلگەن نەرسىلەر. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- توپ-توپ بولۇپ، ئۇلار ئۇنىڭغا كەلگەندە، ئۇنىڭ ئىشىكلىرى ئېچىلىدۇ ۋە ئۇنىڭ ساقچىلىرى ئۇلارغا دەيدۇ. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- اللەھ سىلەرنى قەسەملىرىڭلاردىكى بىھۇدە سۆزلەردىن تۇتمايدۇ، لېكىن سىلەرنى نېمە ئۈچۈن تۇتىدۇ؟) (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- رەھمەت، ئۇلار ئۇنىڭغا خۇشال بولدى؛ ئەگەر قوللىرىنىڭ ئىلگىرى ئەۋەتكەن (گۇناھلىرى) سەۋەبىدىن بىر يامانلىق يەتسە. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- ئاستىدىن ئۆستەڭلار ئېقىپ تۇرىدۇ، ئۇلار ئۇنىڭدا مەڭگۈ قالىدۇ؛ ئەمەل قىلغۇچىلارنىڭ ئەجىرى نېمە دېگەن ياخشى! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- اللەھ ئاسمانلاردىكى ۋە زېمىندىكى نەرسىلەرنى بىلىدۇ؛ ۋە اللەھ. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- اللەھقە ئىتائەت قىلىڭلار ۋە پەيغەمبەرگە ئىتائەت قىلىڭلار؛ ئەگەر يۈز ئۆرۈسەڭلار، ئۇنىڭ ئۈستىگە پەقەت. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- ئۇلارنىڭ ئەجىرى پەرۋەردىگارلىرىنىڭ دەرگاھىدا؛ ئۇلارغا قورقۇنچ يوق ۋە ئۇلار. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- ئۇلار دېدى: «بىز سۆڭەك ۋە توزان بولۇپ قالغاندا، چىنلىقىمىز يېڭىدىن يارىتىلىپ تىرىلدۈرۈلەمدۇق؟» (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- ۋە ئۇلار اللەھتىن باشقا ئۆزلىرىگە ھېچقانداق ئىگە ۋە ياردەمچى تاپالمايدۇ. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- قانچە ۋاقىت تۇردۇڭ؟ ئۇ دېدى: «بىر كۈن ياكى كۈندىن بىر قىسمى تۇردۇم». ئۇ دېدى: (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- مەڭگۈ قىيامەت كۈنىگىچە. اللەھتىن باشقا سىلەرگە (بۇنى) ئېلىپ كېلىدىغان ئىلاھ كىم؟ (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- كىم ياخشى ئەمەل قىلسا – ئەر ياكى ئايال بولسۇن – ۋە مۆمىن بولسا. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- ئۇلار اللەھنىڭ يولىدىن توسىدۇ ۋە ئۇنى ئەگمەكچى بولىدۇ، ئاخىرەتنىمۇ ئىنكار قىلىدۇ. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- خالىغان يەردە (يېڭلار)؛ بۇ دەرەخكە يېقىنلاشماڭلار، يوقسا زالىملاردىن بولۇپ قالىسىلەر. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- ئېيتقىن: «ئى قەۋمىم! ئۆز ئورنىڭلاردا ئەمەل قىلىڭلار، مەنمۇ ئەمەل قىلىمەن؛ يېقىندا بىلىپ قالىسىلەر». (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- شەك-شۈبھىسىزكى، زىيان تارتقۇچىلار قىيامەت كۈنى ئۆزلىرىنى ۋە ئائىلىسىنى زىيانغا ئۇچراتقان كىشىلەردۇر. ئاگاھ بولۇڭلار! (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- كىم ھىدايەت تاپسا، پەقەت ئۆزىنىڭ پايدىسى ئۈچۈن تاپىدۇ؛ كىم ئازسا، پەقەت ئۆزىنىڭ زىيىنىغا ئازىدۇ؛ ھېچكىم. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- كۇفرى قىلغانلار دەيدۇ: «ئۇنىڭغا پەرۋەردىگارىدىن بىر مۆجىزە نېمە ئۈچۈن چۈشۈرۈلمىدى؟» (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- ئۇ سىلەرگە كېچىنى (ئارام ئېلىش ئۈچۈن) ۋە كۈندۈزنى كۆرۈنۈش ئۈچۈن قىلدى. شەك-شۈبھىسىز. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- ھېچقانداق سودا ۋە ھېچقانداق (دوستلۇق) بولمىغان كۈن كېلىشتىن ئىلگىرى. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- ئۇلار ئويلىنىشى ئۈچۈن؛ ئۇلارنىڭ ھەمراھىدا جىننىيلىق يوق؛ ئۇ پەقەت بىر ئاگاھلاندۇرغۇچىدۇر. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
