- اﷲ قا ئىبادەت قىلىڭلار، سىلەرگە ئۇنىڭدىن باشقا ئىلاھ يوق. ئەمەسمۇ قورقۇسىلەر؟ (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23; 23:32
- بىز پەرىشتىلەرگە «ئادەمگە سەجدە قىلىڭلار» دېگەندە، ئىبلىستىن باشقا ھەممىسى سەجدە قىلدى. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ) 2:34; 17:61; 18:50; 20:116
- اﷲ ئاسمانلاردىكى ۋە زېمىندىكى نەرسىلەرنى بىلىدۇ. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 3:29; 5:97; 49:16; 58:7
- جەننەتلەر، ئۇلارنىڭ ئاستىدىن ئۆستەڭلەر ئېقىپ تۇرىدۇ، ئۇلار ئۇ يەردە مەڭگۈ قالىدۇ، بۇ ... (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ) 4:13; 5:85; 9:89; 57:12
- ئۇنىڭ ئەجرى پەرۋەردىگارىنىڭ يېنىدا، ئۇلارغا قورقۇنچ يوق ۋە ئۇلار... (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- پەرۋەردىگارىنىڭ يېنىدا، ئۇلارغا قورقۇنچ يوق ۋە ئۇلار غەمگە بەتمەيدۇ. (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- كىم ھىدايەت تاپسا، ئۆز پايدىسى ئۈچۈن تاپقان بولىدۇ، كىم ئازىپ بولسا... (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- ئۆز پايدىسى ئۈچۈن تاپقان بولىدۇ، كىم ئازىپ بولسا، ئۆز زىيىنى ئۈچۈن ئازىپ بولىدۇ. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- ئۇنىڭغا پەرۋەردىگارى تەرىپىدىن بىر مۆجىزە نېمە ئۈچۈن چۈشۈرۈلمىدى؟ ئېيت: «شۈبھىسىز...» (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- ئىمان كەلتۈرگەن ۋە ياخشى ئەمەللەرنى قىلغانلارغا، ئۇلارغا تۈگىمەس ئەجر بار. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- تىرىكنى ئۆلۈكتىن چىقىرىسەن، ئۆلۈكنى تىرىكتىن چىقىرىسەن. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- كىم اﷲ نازىل قىلغان بويىچە ھۆكۈم قىلمىسا، ئەنە شۇلار... (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- ئاسمانلارنى، زېمىننى ۋە ئۇلارنىڭ ئارىسىدىكى نەرسىلەرنى ئالتە كۈندە ياراتتى. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- شۈبھىسىز اﷲ ئىنسانلارغا پەزىلەت ئىگىسىدۇر، لېكىن كۆپىنچىسى... (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- اﷲ ئۇلارغا زۇلۇم قىلمىدى، لېكىن ئۇلار ئۆزلىرىگە زۇلۇم قىلىۋاتقان ئىدى. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- سىلەرنىڭ گۇناھلىرىڭلارنى كەچۈرۈپ، سىلەرنى جەننەتلەرگە كىرگۈزىدۇ، ئۇلارنىڭ ئاستىدىن ئۆستەڭلەر ئېقىپ تۇرىدۇ. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- سىلەرگە ئۆلۈك، قان، چوشقا گۆشى ۋە اﷲ تىن باشقىنىڭ نامى بىلەن بوغۇزلانغان ھايۋانلارنى ھارام قىلدى. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- مەن پەرۋەردىگارىمغا ئاسىيلىق قىلسام، بۈيۈك كۈندىكى ئازابتىن قورقىمەن. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- پەقەت ئۇلارغا ئىلىم كەلگەندىن كېيىنلا، ئارىلىرىدىكى ھەسەتچىلىك تۈپەيلىدىن. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- ئۇلار نامازنى ئادا قىلدى ۋە بىز ئۇلارغا بەرگەن رىزىقتىن يوشۇرۇن ۋە ئاشكارا خەجلەدى. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- اﷲ تىن باشقا، بىزگە نە پايدا ۋە نە زىيان يەتكۈزەلمەيدىغان نەرسىلەرنى (تاشلاڭ). (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- ئۇلار ساڭا چۈشۈرۈلگەنگە ۋە سەندىن ئىلگىرى چۈشۈرۈلگەنگە ئىمان كەلتۈرىدۇ. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- اﷲ نىڭ ئاسماندىن سۇ چۈشۈرگەنلىكىنى كۆرمىدىڭمۇ؟ (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- ئۇ بىر ئىشنى قارار قىلغاندا، ئۇنىڭغا پەقەت «بول» دېيدۇ، ئۇ دەرھال بولىدۇ. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- مەديەنگە ئۇلارنىڭ قېرىندىشى شۇئەيبنى (ئەۋەتتۇق). ئۇ ئېيتى: «ئېي قەۋمىم! اﷲ قا ئىبادەت قىلىڭلار.» (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- بۇ غەيپ خەۋەرلىرىدىندۇر، بىز ئۇنى ساڭا ۋەھىي قىلىمىز. سەن ئۇلارنىڭ يېنىدا ... ئەمەس ئىدىڭ. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- ئۇلارنىڭ ئەجىلى كەلگەندە، ئۇنى بىر سائەت كېچىكتۈرەلمەيدۇ ۋە ئىلگىرىلىتەلمەيدۇ. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- شەيتاننىڭ ئىزىدىن ماڭماڭلار، شۈبھىسىز ئۇ سىلەرگە ئوچۇق دۈشمەندۇر. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- ئىنسانلار ئىچىدە بەزىلىرى ھېچقانداق ئىلىمسىز اﷲ ھەققىدە تالاش-تارتىش قىلىدۇ. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- اﷲ ئۇنى خالىغان كىشىگە بېرىدۇ، اﷲ كەڭ پەزىلەت ئىگىسىدۇر. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- ھەر بىر جان ئۆزىنىڭ قىلغىنىغا تولۇق مۇكاپاتلىنىدۇ ۋە ئۇلارغا زۇلۇم قىلىنمايدۇ. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- اﷲ ھارام قىلغان جاننى، ئەمما ھەق بىلەن بولمىسا، ئۆلتۈرمەڭلار. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- ئۇ بىر ئىشنى قارار قىلغاندا، ئۇنىڭغا پەقەت «بول» دېيدۇ. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- جەھەننەمنىڭ ئىشىكلىرىدىن كىرىڭلار، ئۇ يەردە مەڭگۈ قالىسىلەر، مۇتەكەببىرلەرنىڭ جايى نەقەدەر يامان! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- ئۆزلىرىگە كىتابتىن پايدا بېرىلگەن كىشىلەرنى كۆرمىدىڭمۇ؟ (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- ئۇلارغا جەننەتلەر بار، ئۇلارنىڭ ئاستىدىن ئۆستەڭلەر ئېقىپ تۇرىدۇ، ئۇلار ئۇ يەردە مەڭگۈ قالىدۇ. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- ئېي قەۋمىم! سىلەر ئۆز ئورنۇڭلاردا ئىشلەڭلار، مەنمۇ ئىشلەيمەن، يېقىندا بىلىسىلەر. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- كىم اﷲ ۋە ئۇنىڭ ئەلچىسىگە قارشىلىق قىلسا، ئۇنىڭغا جەھەننەم ئوتى بار، ئۇ يەردە مەڭگۈ قالىدۇ. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- ئۇلارنىڭ قەلبلىرىدە پردىلەر بار، ئۇنى چۈشىنىشىشى ئۈچۈن، قۇلاقلىرىدا ئېغىرلىق بار. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- قايسى بىر شەھەرگە بىر ئاگاھلاندۇرغۇچى كەلگەن بولسا، ئۇنىڭدىكى باياشاتلار «بىز...» دېدى. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- ئۇلار ئېيتى: «بىز ئۈچۈن پەرۋەردىگارىڭغا دۇئا قىل، ئۇنىڭ نېمە ئىكەنلىكىنى بىزگە بايان قىلسۇن.» (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- ئۇلار «اﷲ» دەيدۇ. ئېيت: «ھەمدۇسانا اﷲ قا بولسۇن!» لېكىن ئۇلارنىڭ كۆپىنچىسى... (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- ئۇنىڭ قەۋمىنىڭ جاۋابى پەقەت «ئۇلارنى چىقىرىۋېتىڭلار...» دېگەندىن باشقا نەرسە ئەمەس ئىدى. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- ئۇلارنىڭ ئاستىدىن ئۆستەڭلەر ئېقىپ تۇرىدۇ، ئۇلار ئۇ يەردە مەڭگۈ قالىدۇ. بۇ بۈيۈك مۇۋەپپەقىيەتتۇر. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- ئەنە شۇلار پەرۋەردىگارىنىڭ ھىدايىتى ئۈستىدە، ئەنە شۇلار مۇۋەپپەقىيەت قازانغۇچىلاردۇر. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- كىمگە خارلىغۇچى ئازاب كېلىدۇ ۋە كىمگە مەڭگۈلۈك ئازاب چۈشىدۇ. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- زېمىندا سەير قىلىپ، ئىنكار قىلغۇچىلارنىڭ ئاقىبىتىنىڭ قانداق بولغانلىقىنى كۆرۈڭلار. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- ئۇلار قوللىرىنىڭ ئىلگىرى ئەۋەتكەنلىرى سەۋەبىدىن ھەرگىز ئارزۇ قىلمايدۇ. اﷲ زالىملارنى ئوبدان بىلىدۇ. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- ئۇ ئۆزىنىڭ يولىدىن كىمنىڭ ئازىپ بولغانلىقىنى ئوبدان بىلىدۇ ۋە ئۇ ئوبدان بىلىدۇ... (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- شۈبھىسىز اﷲ مېنىڭ پەرۋەردىگارىم ۋە سىلەرنىڭ پەرۋەردىگارىڭلاردۇر، ئۇنىڭغا ئىبادەت قىلىڭلار. بۇ توغرا يولدۇر. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- ئىنسانلارغا پەزىلەت ئىگىسىدۇر، لېكىن ئۇلارنىڭ كۆپىنچىسى شۈكۈر قىلمايدۇ. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- ئاسمانلارنى، زېمىننى ۋە ئۇلارنىڭ ئارىسىدىكى نەرسىلەرنى، ھەقلىك ۋە بەلگىلىك مۇددەت بىلەن (ياراتتى). (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- ئۇلارنى قويۇپ بەر، ئۇلار ئۆزلىرىگە ۋەدە قىلىنغان كۈنگە يولۇققۇچە، چۆمۈلۈپ ۋە ئويناپ يۈرىۋەرسۇن. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- ئۇلار ئىمان كەلتۈرگەنلەر بىلەن ئۇچراشقاندا «ئىمان كەلتۈردۇق» دەيدۇ، يالغۇز قالغاندا بولسا... (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- ئۇلار تەۋراتنى، ئىنجىلنى ۋە پەرۋەردىگارىدىن ئۆزلىرىگە چۈشۈرۈلگەننى قىستۇردى. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- ئۇ ئۇلارنىڭ ئالدىدىكىنى ۋە ئارقىسىدىكىنى بىلىدۇ، ئۇلار بۇنى ئىحاطە قىلالمايدۇ... (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- ئاسمانلارنى ۋە زېمىننى ئالتە كۈندە ياراتقان ئۇدۇر. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- شۈبھىسىز بۇنىڭدا سىلەرگە بىر ئايەت بار، ئەگەر ئىمان كەلتۈرسىلەر. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- ئۆزلىرىگە ھىدايەت كەلگەندە، كىشىلەرنى ئىمان كەلتۈرۈشتىن نېمە توسۇۋالدى؟ (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- ئۇلار اﷲ قا شېرىكلەرنى قوشتى، ئۇنىڭ يولىدىن ئازدۇرۇش ئۈچۈن. ئېيت: «لەززەتلىنىڭلار...» (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- ئۇلار ئۆزلىرىدىن بىر ئاگاھلاندۇرغۇچى كەلگەنلىكىگە ھەيران قېلىشتى ۋە كاپىرلار دېدى: «بۇ...» (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- شۈبھىسىز پەرۋەردىگارىڭ ئۆزىنىڭ يولىدىن كىمنىڭ ئازىپ بولغانلىقىنى ئوبدان بىلىدۇ. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- كىشىلەرگە كۆرسىتىش ئۈچۈن مالىنى خەجلەيدىغان ۋە اﷲ قا ئىمان كەلتۈرمەيدىغان كىشىگە ئوخشايدۇ. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- بىز سىلەرگە بەرگەن رىزىقتىن، (ئازاب) كېلىشتىن ئىلگىرى خەجلەڭلار. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- ئاسمانلاردىكى ۋە زېمىندىكى نەرسىلەرنى سىلەرگە بويسۇندۇرۇپ بەردى. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- بىز سىلەرنىڭ بىزنى چاقىرىۋاتقان نەرسەڭلاردىن گۇماندا مىز. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- شۈبھىسىز پەرۋەردىگارىڭ رىزىقنى خالىغان كىشىگە كەڭ قىلىدۇ ۋە تارايتىدۇ. شۈبھىسىز ئۇ... (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- ئاسمانلارنىڭ ۋە زېمىننىڭ ۋە ئۇلارنىڭ ئارىسىدىكى نەرسىلەرنىڭ پەرۋەردىگارى، ئەگەر سىلەر يېقىن ئىشەنچلىك بولساڭلار. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- بىز اﷲ قا ۋە بىزگە چۈشۈرۈلگەنگە ۋە ... چۈشۈرۈلگەنگە ئىمان كەلتۈردۇق. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- زالىملارنى قاتتىق چاققان ۋە ئۆيلىرىدە تىزلىنىپ قالدىلار. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- ئاياللارنىڭ ئۆزلىرى ھەققىدە قىلغان ئىشلىرىدا سىلەرگە گۇناھ يوق. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- پەرۋەردىگارىڭ ئۆزىنىڭ يولىدىن كىمنىڭ ئازىپ بولغانلىقىنى ئوبدان بىلىدۇ ۋە ئۇ... (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- ئۆزىنىڭ ئەمرىدىن بولغان روھنى بەندىلىرىدىن خالىغىنىغا چۈشۈرىدۇ. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- بىز مەريەم ئوغلى ئىيساغا روشەن مۆجىزىلەرنى بەردۇق ۋە ئۇنى روھۇل قۇدۇس بىلەن قۇۋۋەتلىدىك. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- قىيامەت كۈنى ئۇلارنىڭ ئارىسىدا، ئۇلار ئىختىلاپ قىلىۋاتقان نەرسە ھەققىدە ھۆكۈم قىلىش ئۈچۈن. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- ئۇنىڭ ئۈستۈنىنى ئاستىنى قىلدۇق ۋە ئۇلارنىڭ ئۈستىگە پىشۇرۇلغان ساپال تاشلارنى ياغدۇردۇق. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- ئۇلارغا ئاگاھلاندۇرۇش قىلساڭمۇ قىلمىساڭمۇ ئوخشاش، ئۇلار ئىمان كەلتۈرمەيدۇ. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- كىشىلەردىن باشقا، ئەگەر راستچىل بولساڭلار، ئۆلۈمنى ئارزۇ قىلىڭلار. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- اﷲ قا ئىبادەت قىلىڭلار، ئۇنىڭدىن باشقا سىلەرگە ئىلاھ يوق. ئەمەسمۇ قورقۇسىلەر؟ (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- ئەگەر بىز ئۇلارغا ۋەدە قىلغان نەرسىلەرنىڭ بەزىسىنى ساڭا كۆرسەتسەك ياكى سېنى ۋەپات قىلدۇرسەك، ئۇلارنىڭ قايتىشى بىزگەدۇر... (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- ئۇلار ئېيتى: «ئۆلۈپ توپا ۋە سۆڭەك بولغاندا، بىز قايتىدىن تىرىلدۈرۈلىمىز؟» (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- شۈبھىسىز پەزىلەت اﷲ نىڭ قولىدا، ئۇنى خالىغان كىشىگە بېرىدۇ، اﷲ... (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- يوشۇرۇن ۋە ئاشكارىنى بىلگۈچىگە (قايتۇرۇلىسىلەر) ۋە قىلغان ئەمەللىرىڭلارنى سىلەرگە خەۋەر قىلىدۇ. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- ئېي ئىمان كەلتۈرگەنلەر! اﷲ نىڭ سىلەرگە قىلغان نېمىتىنى ياد قىلىڭلار، ۋاقتىدا... (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- بىز سەندىن ئىلگىرى پەقەت ئەر كىشىلەرنى پەيغەمبەر قىلىپ ئەۋەتتۇق، ئۇلارغا ۋەھىي قىلاتتۇق. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- ئۇنىڭ گۇناھلىرىنى كەچۈرۈپ، ئۇنى جەننەتلەرگە كىرگۈزىدۇ، ئۇلارنىڭ ئاستىدىن ئۆستەڭلەر ئېقىپ تۇرىدۇ. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- كېسەل ياكى سەپەردە بولسا، باشقا كۈنلەردىن سانى (تولدۇرىدۇ). (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- ئۇلار پەقەت گۇمانغا ئەگىشىدۇ ۋە پەقەت تەخمىن قىلىدۇ. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- اﷲ ۋە ئاخىرەت كۈنىگە ئۈمىد قىلىدىغان كىشى ئۈچۈن گۈزەل ئۈلگىدۇر. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- بىز ئاسمانلارنى، زېمىننى ۋە ئۇلارنىڭ ئارىسىدىكى نەرسىلەرنى ھەقلىك تەرىپىدىنلا ياراتتۇق. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- قولۇڭنى ياقىڭغا سال، ئۇ ئەيىبسىز ئاپئاق بولۇپ چىقىدۇ. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- ئۇ رەھمىتىنى خالىغان كىشىگە خاس قىلىدۇ، اﷲ كەڭ پەزىلەت ئىگىسىدۇر. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- اﷲ نىڭ ئاسمانلار ۋە زېمىننىڭ پادىشاھلىقى ئىكەنلىكىنى بىلمەمسەن؟ (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- سىلەر ئۆزۈڭلار ئۈچۈن ئىلگىرى ئەۋەتكەن ياخشىلىقنى اﷲ نىڭ يېنىدا تاپىسىلەر. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- قا يەردىن چىقساڭمۇ، يۈزۈڭنى مەسجىدىل ھەرەمگە قاراتقىن. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- بۇلاردىن ئىلگىرى نۇرغۇن كىشىلەر ئۆتكەن، اﷲ نىڭ قانۇنىدا ھەرگىز ئۆزگەرتىش تاپالمايسەن. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- ئاسمانلاردىكى ۋە زېمىندىكى نەرسىلەر كىمنىڭ مۈلكى بولسا، شۇنى. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- ھېچبىر ئايال ھامىلىدار بولمايدۇ ۋە تۇغمايدۇ، مەگەر ئۇنىڭ ئىلمى بىلەن. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- كېچىنى، ئۇ قۇياش ۋە ئاينى بويسۇندۇردى، ھەر بىرى بەلگىلەنگەن مۇددەت بىلەن يۈرىدۇ. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- ئۇلارنىڭ ئاستىدىن ئۆستەڭلەر ئېقىپ تۇرىدۇ، ئۇلار ئۇ يەردە مەڭگۈ قالىدۇ، بۇ ... نىڭ مۇكاپاتىدۇر. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- ئۇ ئېيتى: «ئۇنداق ئەمەس، سىلەرنىڭ نەپسىڭلار سىلەرگە بىر ئىشنى زىننەتلىك كۆرسەتتى. سەۋر قىلىش گۈزەلدۇر.» (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- ئاسمانلاردىكى ۋە زېمىندىكى نەرسىلەر ۋە اﷲ... (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- ئۇلارغا قانداق بىر پەيغەمبەر كەلگەن بولسا، ئۇنى مەسخىرە قىلىدىغان. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- ئۇلار ئېيتى: «ئېي مۇسا! يە سەن تاشلا، ياكى بىز تاشلىغۇچى بولايلىمۇ؟» (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- سىلەرنى ۋەپات قىلدۇرىدىغان ئۇدۇر، بەزىڭلار ئەڭ ناچار يېشىغا قايتۇرۇلىدۇ، شۇنىڭ بىلەن... (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- ئۇلارغا پەرۋەردىگارىنىڭ يېنىدا جەننەتلەر بار، ئۇلارنىڭ ئاستىدىن ئۆستەڭلەر ئېقىپ تۇرىدۇ، ئۇلار ئۇ يەردە مەڭگۈ قالىدۇ. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- بىز ئۇلارنىڭ قەلبلىرىگە پردىلەر سالدۇق، ئۇنى چۈشىنىشىشى ئۈچۈن، قۇلاقلىرىغا ... (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- شۈبھىسىز اﷲ نىڭ ۋەدىسى ھەقتۇر، لېكىن ئۇلارنىڭ كۆپىنچىسى بىلمەيدۇ. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- بۇ ئۇلارنىڭ اﷲ ۋە ئۇنىڭ ئەلچىسىگە قارشىلىق قىلغانلىقلىرى ئۈچۈندۇر. كىم اﷲ قا قارشىلىق قىلسا... (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- ئۇ كۈنى ئۇلارنى چاقىرىپ ئېيتىدۇ: «مېنىڭ شېرىكلىرىم قەيەردە، سىلەر گۇمان قىلاتتۇڭلار؟» (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- ئاسمانلار ۋە زېمىننى ياراتقان اﷲ نى كۆرمەمدىمۇ؟ (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- سېنى تۇپراقتىن، ئاندىن بىر نۇتپىدىن، ئاندىن ... ياراتقاننى (ئېسىڭغا كەلتۈر). (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- ئۇلار ئېيتىدى: «پەرۋەردىگارىمىز! بىزگە بىر پەيغەمبەر ئەۋەتسەڭچى، بىز سېنىڭ ئايەتلىرىڭگە ئەگىشەتتۇق!» (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- ئاندىن ئۇلارنىڭ قايتىشى پەرۋەردىگارىغا بولىدۇ، ئاندىن قىلغان ئەمەللىرىنى ئۇلارغا خەۋەر قىلىدۇ. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- ئۇلارنىڭ بۇ ھەقتە ھېچقانداق ئىلمى يوق، پەقەت ... (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- بىز ئاتا-بوۋىلىرىمىزنى بىر دىندا تاپتۇق ۋە بىز ئۇلارنىڭ ئىزىدىن ماڭىمىز. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- كىتاب بېرىلگەن كىشىلەر پەقەت ئۆزلىرىگە ئىلىم كەلگەندىن كېيىنلا ئىختىلاپ قىلدى. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- ئىبراھىم: «پەرۋەردىگارىم! بۇ شەھەرنى تىنچلىق شەھىرى قىلغىن» دېگەن ۋاقىتنى ئېسىڭغا كەلتۈر. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- ئۇ سىلەرگە قۇلاق، كۆز ۋە قەلب بەردى، لېكىن ئازلا شۈكۈر قىلىسىلەر. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- اﷲ نىڭ ئايەتلىرى ھەققىدە، ئۆزلىرىگە كەلگەن ھېچقانداق دەلىلسىز، تالاش-تارتىش قىلىدىغانلار. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- ئىبراھىمنىڭ دىنىغا ئەگىشىڭلار، ئۇ ھەنىپ ئىدى ۋە مۇشرىكلاردىن ئەمەس ئىدى. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- سىلەرنى فىرئەۋن تەبىئىسىدىن قۇتقۇزغان ۋاقتىمىزنى ئېسىڭغا كەلتۈر، ئۇلار سىلەرگە قاتتىق ئازاب بەرەتتى. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- بۇ توغرا دىندۇر، لېكىن كۆپىنچە كىشىلەر بىلمەيدۇ. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- اﷲ نىڭ زېمىندىكى نەرسىلەرنى سىلەرگە بويسۇندۇرۇپ بەرگەنلىكىنى كۆرمەمسەن؟ (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- كاپىرلار ئېيتى: «بۇ ئوچۇق سېھىردۇر.» (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- ئۇلارغا بىزنىڭ روشەن ئايەتلىرىمىز ئوقۇلغاندا، كاپىرلار دەيدۇ... (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- ئاستىدىن ئۆستەڭلەر ئېقىپ تۇرىدىغان جەننەتلەر، ئۇلار ئۇ يەردە مەڭگۈ قالىدۇ. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- خالىغىنىنى، شۈبھىسىز اﷲ ھەممە نەرسىگە قادىردۇر. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- سىلەرنىڭ گۇناھلىرىڭلارنى كەچۈرۈپ، سىلەرنى بەلگىلەنگەن مۇددەتكىچە كېچىكتۈرۈش ئۈچۈن. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- سىلەر بىزنى ئاتا-بوۋىلىرىمىز ئىبادەت قىلغان نەرسىدىن توسماقچىمۇسىلەر؟ (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- پەرۋەردىگارىڭ پەرىشتىلەرگە: «مەن لايدىن بىر بەشەر يارىتىمەن» دېگەن ۋاقتىنى ئېسىڭغا كەلتۈر. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- رەھمىتىدىن ئىلگىرى شاماللارنى خۇشخەۋەرچى قىلىپ ئەۋەتكۈچى ئۇدۇر. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- ئېيت: «زېمىندا سەير قىلىپ، ... نىڭ ئاقىبىتىنىڭ قانداق بولغانلىقىنى كۆرۈڭلار.» (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- شۈبھىسىز ئاسمانلار ۋە زېمىننىڭ يارىتىلىشىدا، كېچە ۋە كۈندۈزنىڭ ئالمىشىشىدا (ئايەتلەر بار). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- كىم اﷲ قا ياخشى قەرز بېرىدۇ، ئۇنىڭغا ئۇنى كۆپەيتىپ بېرىدۇ؟ (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- ئۇلارنىڭ ئارىسىدا اﷲ نازىل قىلغان بويىچە ھۆكۈم قىل، ئۇلارنىڭ نەپسى خاھىشلىرىغا ئەگەشمە. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- ئۇلار پەرىشتىلەرنىڭ كېلىشىدىن ياكى پەرۋەردىگارىڭنىڭ (ئەمرىنىڭ) كېلىشىدىن باشقا نېمىنى كۈتۈۋاتىدۇ؟ (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- شۈبھىسىز اﷲ قا يالغان توقۇغانلار ھەرگىز مەقسەتكە ئېرىشەلمەيدۇ. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- فىرئەۋن تەبىئىسى ۋە ئۇلاردىن ئىلگىرىكىلەرنىڭ ئادىتىگە ئوخشاش، ئۇلار بىزنىڭ ئايەتلىرىمىزنى يالغان دېدى. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- ياخشى ئەمەللەرنى قىلىۋاتقان مۆمىنلەرگە، ئۇلارغا بۈيۈك مۇكاپات بارلىقىنى خۇشخەۋەر قىل. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- اﷲ بەندىلىرىدىن خالىغىنىغا رىزىقنى كەڭ قىلىدۇ ۋە تارايتىدۇ. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- سىلەر يوشۇرۇن ۋە ئاشكارىنى بىلگۈچىگە قايتۇرۇلىسىلەر ۋە قىلغان ئەمەللىرىڭلارنى سىلەرگە خەۋەر قىلىدۇ. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- قانداشلار، اﷲ نىڭ كىتابىدا بىر-بىرىگە تېخىمۇ يېقىندۇر. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — پەرز / ۋاجىب (قىلىش شەرت؛ تاشلىسا گۇناھ)
- mustahabb / mandub (مستحب / مندوب) — مۇستەھەب / مەندۇب (قىلسا ساۋاب، تاشلىسا گۇناھ ئەمەس)
- mubah (مباح) — مۇباھ (نە ساۋاب نە گۇناھ)
- makruh (مكروه) — مەكرۇھ (ياقتۇرۇلمايدۇ، قىلىش تەشۋىق قىلىنمايدۇ، ئەمما قىلسا گۇناھ ئەمەس)
- haram (حرام) — ھارام (قىلىش گۇناھ)
- halal (حلال، ھالال / قانۇنىي) — مۇباھ ۋە مۇستەھەبنى ئۆز ئىچىگە ئالىدۇ — ھارام بولمىغان ھەر نەرسە
- پەقەت ئاللاھقىلا ئىبادەت قىلىڭلار ۋە ئۇنىڭدىن ياردەم تىلەڭلار. 1:5
- پەقەت ئاللاھقىلا ئىبادەت قىلىڭلار 2:21
- ئاللاھقا ھېچكىمنى شېرىك كەلتۈرمەڭلار 2:22
- ئاللاھ كەچۈرۈم قىلغۇچىدۇر (تەۋبىنى قوبۇل قىلغۇچىدۇر)، ئۇ ئادەم (عَلَيْهِ ٱلسَّلَامُ) نىڭ تەۋبىسىنى قوبۇل قىلدى. 2:37
- ھەقنى باتىل بىلەن ئارىلاشتۇرماڭلار ۋە ھەقنى يوشۇرماڭلار. 2:42
- نامازنى ئوقۇڭلار ۋە زاكاتنى بېرىڭلار. 2:43
- باشقىلارغا ياخشىلىقنى بۇيرۇشتىن ئاۋۋال ئۆزىڭلار ئۇنىڭغا ئەمەل قىلىڭلار 2:44
- بارلىق ئىشلىرىڭلاردا ئاللاھتىن ياردەم تىلەڭلار 2:45
- بۇزغۇنچىلىققا كىرىشمەڭلار ياكى تارقاتماڭلار 2:60
- كىشىلەرنى ئىبادەتخانىلارغا بېرىشتىن توسماڭلار 2:114
- مەسچىتنىڭ مۇقەددەسلىكىگە ھۆرمەت قىلىڭلار. ناماز ئوقۇيدىغان جايلارنى پاكىز ۋە تازا تۇتۇڭلار 2:125
- ئاللاھنى ئېسىڭلارغا كەلتۈرۈڭلار (ناماز، تەسبىھ ۋە باشقىلار ئارقىلىق)، ئۇ سىلەرنى ئېسىگە ئالىدۇ، ۋە ئۇنىڭغا شۈكۈر قىلىڭلار. 2:152
- مۇسىبەتتە سەبر قىلىڭلار 2:153
- شەيتاننىڭ ئىزىدىن يۈرمەڭلار، ئۇ ئوچۇق دۈشمەندۇر. 2:168
- ھېچكىمگە كورۇنە تەۋە بولماڭلار 2:170
- بارلىق ئامانەتلەرنى ئادا قىلىڭلار ۋە ساقلاڭلار. دىنىي ۋەزىپىلىرىڭلارنى سەمىمىي ئادا قىلىڭلار. قەسەملىرىڭلارنى ۋە ئەھدىلىرىڭلارنى ئادا قىلىڭلار. ۋەدىلەرنى، بولۇپمۇ ئاللاھقا بەرگەن ۋەدىلەرنى ئادا قىلىڭلار. مۇھتاجلارغا ياردەم قىلىڭلار ۋە قىيىنچىلىقلارنى يېنىكلىتىڭلار. ئاللاھنىڭ مەرھەمىتىنى يوقىتىدىغان گۇناھلاردىن ساقلىنىڭلار. كىبىر سىلەرنى زۇلۇمغا ئېلىپ بېرىشىگە يول قويماڭلار 2:177
- قىساس (جازادا باراۋەرلىك قانۇنى) دا سىلەرگە ھايات بار. 2:179
- رامىزان ئېيىدا روزا تۇتۇڭلار. تەقۋادار بولۇش ئۈچۈن بەلگىلەنگەن روزىنى تۇتۇڭلار. 2:183
- قۇرئانغا يېتەكچىلىكنىڭ ئەڭ ئاخىرقى مەنبەسى سۈپىتىدە ھۆرمەت قىلىڭلار 2:185
- بىر-بىرىڭلارنىڭ ماللىرىنى ناھەق يېمەڭلار ۋە (دەۋالىرىڭلارنى تەقدىم قىلىشتىن ئىلگىرى) ھاكىملارغا پارا بەرمەڭلار. 2:188
- باشقىلارغا سۆز ياكى ھەرىكەت بىلەن زۇلۇم قىلماڭلار. ھەرگىز تاجاۋۇزچى بولۇپ ئۇرۇشماڭلار، پەقەت قوغداش ئۈچۈنلا ئۇرۇشۇڭلار 2:190
- يېتىملەرنى قوغداڭلار. يېتىملەر توغرىسىدا، ئۇلارنىڭ ماللىرىدا ئەمىنلىك بىلەن ئىش قىلىڭلار ۋە ئۇلارنىڭ ماللىرىنى يېمەڭلار. 2:220
- تەۋبە قىلىڭلار ۋە ئاللاھتىن مەغپىرەت تىلەڭلار. ھەيز ۋاقتىدا جىنسىي مۇناسىۋەتتە بولماڭلار. (جىسمانىي ۋە روھىي) پاكلىقنى ساقلاڭلار 2:222
- ئائىلىڭلارغا بولغان مەسئۇلىيەتلىرىڭلارنى ئادا قىلىڭلار 2:233
- رەھبەرلەرنى ئۇلارنىڭ لاياقىتىگە قاراپ تاللاڭلار 2:247
- دىندا ھېچقانداق زورلاش يوق 2:256
- ماللارنى سەدىقىدە خەجلەڭلار. مال ۋە ۋاقىت جەھەتتە سەخىي بولۇڭلار 2:261
- سەدىقىڭلارنى ئۆز سەخىيلىكىڭلار بىلەن ماختاپ بۇزماڭلار 2:264
- شەيتان سىلەرنى نامراتلىق بىلەن قورقىتىدۇ ۋە سىلەرگە يامان ئىشلارنى (گۇناھلارنى) بۇيرۇيدۇ. 2:268
- مۇھتاجلارنى ئىزدەڭلار ۋە ئۇلارغا ياردەم قىلىڭلار 2:273
- سۇدچىلىق ياكى پايدا ئېلىش بىلەن شۇغۇللانماڭلار. پايدا ئاساسىدىكى مالنى يېمەڭلار. رىبا (سۇد) نى يېمەڭلار. 2:275
- قەرزدار قىيىنچىلىقتا بولسا، ئۇنىڭغا تۆلەش ئۈچۈن تېخىمۇ كۆپ ۋاقىت بېرىڭلار 2:280
- سودا ئىشلىرىدا سۆزىڭلارغا ۋەپا قىلىڭلار. پۇل-مۇئامىلە ئىشلىرىڭلاردا راستچىل بولۇڭلار. بارلىق ۋەدىلىرىڭلاردا ئەمىن بولۇڭلار. بەلگىلەنگەن مۇددەتكە قەرز توختاسىڭلار، ئۇنى يېزىۋېلىڭلار. ھەر قېتىم سودا ئەھدىسى تۈزگىنىڭلاردا گۇۋاھچى تۇتۇڭلار. 2:282
- بارلىق ئامانەتلەرنى ئادا قىلىڭلار ۋە ساقلاڭلار 2:283
- نازىل قىلىنغان كىتابلارغا ۋە بارلىق پەيغەمبەرلەرگە ئىمان كەلتۈرۈڭلار 2:285
- ئاللاھ ھېچقانداق جانغا ئۇنىڭ تاقىتى تارتمايدىغان نەرسىنى يۈكلىمەيدۇ. ئۇلار قىلغان (ياخشى) ئىشلىرىنىڭ ساۋابىنى ئالىدۇ ۋە قىلغان (يامان) ئىشلىرىنىڭ جازاسىنى تارتىدۇ. ئاللاھ ھېچقانداق جانغا ئۇنىڭ تاقىتى تارتمايدىغان نەرسىنى يۈكلىمەيدۇ؛ بىزمۇ شۇنداق قىلمايلى. قىيىنچىلىقتىمۇ ئاللاھنىڭ پىلانىغا ئىشىنىڭلار 2:286
- كىم ۋەدىسىگە ۋەپا قىلىپ، ئاللاھتىن قورقسا، ئاللاھ تەقۋادارلارنى سۆيدۇ. 3:76
- ھەجنى قىلالىساڭلار قىلىڭلار 3:97
- بۆلۈنۈپ كەتمەڭلار 3:103
- ياخشىلىققا بۇيرۇڭلار ۋە يامانلىقتىن توسۇڭلار. جەمئىيىتىڭلاردا ياخشىلىقنى رىغبەتلەندۈرۈڭلار. باشقىلارنى ئاللاھنى ئەسكە تەكلىپ قىلىڭلار 3:104
- مۆمىنلەر ئاللاھقا تەۋەككۈل قىلسۇن. 3:122
- رىبا (سۇد) نى يېمەڭلار. 3:130
- رەھمەتكە ئېرىشىش ئۈچۈن ئاللاھقا ۋە ئۇنىڭ پەيغەمبىرىگە ئىتائەت قىلىڭلار. 3:132
- ئاللاھ پۇل-مېنىڭ بار-يوقىدا (ئاللاھ يولىدا) خەجلەيدىغان، ئاچچىقىنى ئىچىگە يۇتقان ۋە كىشىلەرنى كەچۈرىدىغان كىشىلەرنى سۆيدۇ. 3:134
- ئاچچىقىڭلارنى تىزگىنلەڭلار. 3:134
- باشقىلارنىڭ خاتالىقلىرىنى كەچۈرۈڭلار 3:135
- سۆزدە قوپال بولماڭلار. سىلەردىن پەرقلىق بولغانلارغا سەبر قىلىڭلار 3:159
- ئەگەر ئاللاھ سىلەرگە ياردەم قىلسا، ھېچكىم سىلەرنى يېڭەلمەيدۇ؛ ئەگەر ئۇ سىلەرنى تاشلىسا، ئۇنىڭدىن قالغۇچى كىم سىلەرگە ياردەم قىلالايدۇ؟ 3:160
- ھەر بىر جان ئۆلۈمنى تېتىيدۇ. پەقەت قىيامەت كۈنىدە سىلەرگە ئەجىرىڭلار تولۇق بېرىلىدۇ. 3:185
- تەبىئەتنىڭ ئەجايىپلىرى ۋە بۇ كائىناتنىڭ يارىتىلىشى ئۈستىدە چوڭقۇر ئويلىنىڭلار. ئاللاھ كائىناتنى مەنىسى ۋە مەقسەت بىلەن ياراتقانلىقىنى بىلىڭلار 3:191
- ئەر-ئاياللار قىلغان ئىشلىرىغا تەڭ ساۋاب ئالىدۇ 3:195
- رەببىدىن قورققانلار ئۈچۈن، ئاستىدىن ئۆستەڭلەر ئېقىپ تۇرىدىغان باغلار (جەننەتتە) بار؛ ئۇلار ئۇ يەردە مەڭگۈ قالىدۇ، بۇ ئاللاھتىن كەلگەن مېھمانچىلىقتۇر. 3:198
- ھەر بىر ئىشتا ئاللاھنىڭ رازىلىقىنى كۆزدە تۇتۇڭلار. 3:200
- رەببىڭلارغا ئىتائەت قىلىڭلار، ئۇنىڭدىن قورقۇڭلار ۋە (قېرىنداشلىق ئالاقىلىرىنى) ئۈزمەڭلار. 4:1
- يېتىملەرگە ماللىرىنى بېرىڭلار ۋە (ئۆزۈڭلارنىڭ) ناچار ماللىرىنى (ئۇلارنىڭ) پاكىز ماللىرى بىلەن ئالماشتۇرماڭلار؛ ۋە ئۇلارنىڭ ماللىرىنى ئۆز ماللىرىڭلارغا قوشۇپ يېمەڭلار. 4:2
- ئۆزلىرى توي قىلىدىغان ئاياللارغا مەھرىنى (نىكاھ ۋاقتىدا ئەر ئايالغا بېرىشى شەرت بولغان توي ھەدىيىسى) خۇش كۆڭۈل بىلەن بېرىڭلار. 4:4
- يېتىملەرنىڭ ھوقۇقلىرىنى قوغداڭلار 4:6
- ئۆلگەن كىشىنىڭ مېلى ئائىلە ئەزالىرى ئارىسىدا تەقسىملىنىشى كېرەك. ئاياللارنىڭ مىراس ھوقۇقى بار 4:7
- يېتىملەرنىڭ مېلىنى ناھەق يېمەڭلار 4:10
- مىراس توغرىسىدىكى ئەمرلەرگە ئىتائەت قىلىڭلار 4:11
- ئاياللارنى ئۇلارنىڭ خاھىشىغا قارشى مىراسقا ئېلىش ھارام قىلىندى، ۋە سىلەر ئۇلارغا قاتتىق مۇئامىلە قىلماڭلار. ئۇلار (ئاياللار) بىلەن ئىززەت-ھۆرمەت بىلەن ياشاڭلار. ئاياللارنىڭ ھوقۇقلىرىغا ھۆرمەت قىلىڭلار ۋە رىئايە قىلىڭلار. جۈپتىڭلارغا مېھرىبانلىق ۋە رەھىمدىللىق بىلەن مۇئامىلە قىلىڭلار. ئاياللارغا ھۆرمەت ۋە ئادىللىق بىلەن مۇئامىلە قىلىڭلار 4:19
- قان قېرىنداشلىرىڭلار بىلەن توي قىلماڭلار 4:23
- ئۆزلىرىڭلارنى (ياكى بىر-بىرىڭلارنى) ئۆلتۈرمەڭلار. شۈبھىسىزكى، ئاللاھ سىلەرگە رەھىمدىلدۇر. بىر-بىرىڭلارنىڭ ماللىرىنى ناھەق يېمەڭلار 4:29
- ئەگەر سىلەر چوڭ گۇناھلاردىن ساقلىنىپ قالساڭلار، ئاللاھ سىلەردىن (كىچىك) گۇناھلىرىڭلارنى ئۆچۈرىدۇ ۋە سىلەرنى ئۇلۇغ دەرىجىگە (يەنى جەننەتكە) كىرگۈزىدۇ. 4:31
- ئاللاھ بەزىڭلارنى بەزىڭلاردىن ئۈستۈن قىلغان نەرسىلەرنى ئارزۇ قىلماڭلار. ھەسەتچىلىك ۋە كۆنەشتىن ساقلىنىڭلار 4:32
- ئەرلەر ئاياللارنىڭ قوغدىغۇچىلىرى ۋە بېقۇغۇچىلىرىدۇر، چۈنكى ئاللاھ بەزىلىرىنى بەزىلىرىدىن ئۈستۈن قىلدى ۋە ئۇلار (ئاياللارنى بېقىش ئۈچۈن) ماللىرىدىن خەجلايدۇ. ئەر ئائىلىنىڭ قوغدىغۇچىسى ۋە تىرەكسىدۇر 4:34
- ئاللاھقا ئىبادەت قىلىڭلار ۋە ئۇنىڭغا ھېچنىمىنى شېرىك كەلتۈرمەڭلار، ئاتا-ئانىغا، تۇغقانلارغا، يېتىملەرگە، مىسكىنلەرگە، قوشنىلارغا، يېنىڭلاردىكى ھەمسۆھبەتكە، يولۇچىغا ۋە قول ئاستىدىكى قۇللارغا ياخشىلىق قىلىڭلار. ئاللاھ كىبىرلىنىدىغان ۋە ماختاشقا ئۇرۇنىدىغان كىشىلەرنى سۆيمەيدۇ. باشقىلارغا ياخشىلىق قىلىڭلار. ئاجىزلارغا رەھىم قىلىڭلار. تۇغقانچىلىق ئالاقىلىرىنى ساقلاڭلار ۋە تۇغقانلارغا ھۆرمەت قىلىڭلار. 4:36
- خېسىل بولماڭلار 4:37
- ئاللاھ ئۆزىگە شېرىك كەلتۈرۈلۈشىنى كەچۈرمەيدۇ، ئەمما بۇنىڭ سىرتىدىكىنى ئۆزى خالىغان كىشىگە كەچۈرىدۇ. 4:48
- باشقىلارغا ھەسەت قىلماڭلار 4:54
- ئاللاھ سىلەرگە ئامانەتلەرنى ئىگىلىرىگە تاپشۇرۇشنى ۋە كىشىلەر ئارىسىدا ھۆكۈم چىقارغىنىڭلاردا ئادىل ھۆكۈم چىقىرىشنى بۇيرۇيدۇ. 4:58
- ئاللاھقا ۋە ئۇنىڭ پەيغەمبىرىگە ئىتائەت قىلىڭلار. ئۆز ئاراڭلاردىكى ئامىرلارغا ھۆرمەت قىلىڭلار 4:59
- ئاجىز ۋە ئەجىز كىشىلەرگە زۇلۇم قىلماڭلار 4:75
- سىلەرگە كەلگەن ياخشىلىقلارنىڭ ھەممىسى ئاللاھتىندۇر، سىلەرگە كەلگەن يامانلىقلار بولسا ئۆزۈڭلاردىندۇر. 4:79
- كىم پەيغەمبەرگە (مۇھەممەد ﷺ) ئىتائەت قىلسا، ئۇ ئاللاھقا ئىتائەت قىلغان بولىدۇ. 4:80
- كىم ياخشى ئىشقا شاپائەت قىلسا، ئۇنىڭغا ئۇنىڭ ساۋابىدىن ئۈلۈش بار، كىم يامان ئىشقا شاپائەت قىلسا، ئۇنىڭغا ئۇنىڭ ۋەبالىدىن ئۈلۈش بار. 4:85
- بىر مۆمىننىڭ ئۆزىدىن باشقا بىر مۆمىننى خاتالىقتىن باشقا ئۆلتۈرۈشى جايز ئەمەس. 4:92
- كىم بىر مۆمىننى قەستەن ئۆلتۈرۈپ قويۇپ، ئۇنىڭ جازاسى دوزاخ بولۇپ، ئۇ يەردە مەڭگۈ قالىدۇ. ئۇنىڭغا ئاللاھنىڭ غەزىبى ۋە لەنئىتى بار بولۇپ، ئۇنىڭغا كاتتا ئازاب تەييارلانغان. 4:93
- كىم ئاللاھ يولىدا (ئۆيىدىن) ھىجرەت قىلسا، يېرىمۇ يەردە نۇرغۇن پاناھگاھ ۋە كەڭچىلىك تېپىدۇ. 4:100
- نامازلىرىڭلارغا ھەر ۋاقىت رىئايە قىلىڭلار 4:103
- ئامانەتكە خىيانەت قىلىدىغانلارنى قوللىماڭلار ياكى ئۇلارنىڭ ۋەكىلى بولماڭلار 4:105
- ئاللاھتىن مەغپىرەت تىلەڭلار، شۈبھىسىزكى، ئاللاھ بەك مەغپىرەت قىلغۇچى، بەك مېھرىباندۇر. 4:106
- ئى ئىمان كەلتۈرگەنلەر! ئاللاھ ئۈچۈن گۇۋاھچى بولۇپ، ئۆزۈڭلارنىڭ ياكى ئاتا-ئانىڭلارنىڭ ياكى تۇغقانلىرىڭلارنىڭ زىيىنىغا بولسىمۇ، ئۇ باي ياكى نامرات بولسىمۇ، ئادىللىق بىلەن تىك تۇرۇڭلار. ئادىللىقنى كېچىكتۈرمەڭلار؛ زۇلۇمنى تۈزىتىش ئۈچۈن دەرھال ھەرىكەت قىلىڭلار 4:135
- مۇناپىقلار ئاللاھنى ئالدىماقچى بولىدۇ، ئەمما ئۇ ئۇلارنى ئالدايدۇ. 4:142
- مۇناپىقلار دوزاخنىڭ ئەڭ تۈۋەن (قەۋىتى) دە بولىدۇ، سەن ئۇلارغا ھەرگىز ياردەمچى تاپالمايسەن. 4:145
- ئاللاھ زۇلۇمغا ئۇچرىغان كىشىدىن باشقا، يامانلىقنى ئاشكارا سۆزلەشنى سۆيمەيدۇ. 4:148
- پەيغەمبەرلەر خۇش خەۋەر بەرگۈچىلەر ۋە ئاگاھلاندۇرغۇچىلار بولۇپ (ئەۋەتىلدى)، تەكى پەيغەمبەرلەر (كەلگەندىن) كېيىن كىشىلەرنىڭ ئاللاھقا قارشى ھېچقانداق پايدىسى بولمىسۇن. 4:165
- ئەھدىلىرىڭلار ۋە ۋەدىلىرىڭلارغا ۋەپا قىلىڭلار 5:1
- ياخشىلىق ۋە تەقۋادا بىر-بىرىڭلارغا ياردەم قىلىڭلار، گۇناھ ۋە دۈشمەنلىكتە ياردەم قىلماڭلار 5:2
- ئۆلۈك، قان ۋە چوشقا گۆشىنى يېمەڭلار 5:3
- ئادىل بولۇڭلار؛ باشقىلارنىڭ دۈشمەنلىكى ۋە ئۆچمەنلىكى سىلەرنى ئادىللىقتىن ئايرىپ قويمايدۇ. ئىشلىرىڭلاردا ئادىل ۋە تولۇق بولۇڭلار. ئادىللىقنىڭ تەقۋاغا يېقىن ئىكەنلىكىنى بىلىڭلار. ئادىللىقنى كېچىكتۈرمەڭلار؛ زۇلۇمنى تۈزىتىش ئۈچۈن دەرھال ھەرىكەت قىلىڭلار 5:8
- ئاللاھقا يېقىنلىشىش ئۈچۈن ۋاسىتە ئىزدەڭلار ۋە مۇۋەپپەقىيەت قازىنىش ئۈچۈن ئۇنىڭ يولىدا قولىڭلاردىن كېلىشىچە تىرىشىڭلار. 5:35
- قەسەملىرىڭلار ۋە ئەھدىلىرىڭلارغا ۋەپا قىلىڭلار 5:89
- ئىچىملىكلەر ۋە ھارامدىن ساقلىنىڭلار. ئىچىملىكلەر (بارلىق خىل ھاراقلىق ئىچىملىكلەر)، قىمار، بۇتلار ۋە پال ئوقلىرىدىن قاتتىق ساقلىنىڭلار، بۇلارنىڭ ھەممىسى شەيتاننىڭ پالا-چال ئىشلىرىدۇر. 5:90
- سىلەر ھەج ياكى ئۆمرە ئۈچۈن ئىھرام ھالىتىدە بولغىنىڭلاردا، ۋەھشىي ھايۋان ئوۋلىماڭلار. 5:95
- ئەگەر سىلەرگە ئېنىق چۈشەندۈرۈلسە، سىلەرگە قىيىنچىلىق كەلتۈرۈپ چىقىرىدىغان ئىشلارنى سورىماڭلار. 5:101
- باشقىلارنىڭ بۇتلىرىغا تىلىم ئۇرماڭلار. ئۇلار (كۇففارلار) ئاللاھتىن باشقا ئىبادەت قىلىدىغان نەرسىلەرگە تىلىم ئۇرماڭلار، ئۇنداق بولسا ئۇلارمۇ بىلىمسىزلىك بىلەن ئاللاھقا تىلىم ئۇرىدۇ. 6:108
- ئەگەر سىلەر يېرىمۇ يەردىكى كۆپچىلىككە ئىتائەت قىلساڭلار، ئۇلار سىلەرنى ئاللاھنىڭ يولىدىن تۈزۈۋېتىدۇ. ئۇلار پەقەت گۇمانغا ئەگىشىدۇ ۋە پەقەت يالغان سۆزلەيدۇ. 6:116
- (ئى ئىنسانلار!) بارلىق گۇناھلارنى، ئاشكارا ۋە يوشۇرۇن، تاشلاڭلار. 6:120
- (ئى ئىمان كەلتۈرگەنلەر!) ئۈستىگە (سويۇش ۋاقتىدا) ئاللاھنىڭ ئىسمى ئېيتىلمىغان گۆشنى يېمەڭلار. 6:121
- ئاللاھ كىمنى ھىدايەت قىلىشنى خالىسا، ئۇنىڭ كۆكسىنى ئىسلامغا ئاچىدۇ، كىمنى ئازدۇرۇشنى خالىسا، ئۇنىڭ كۆكسىنى تار ۋە قىسىلغان قىلىپ قويىدۇ. 6:125
- خەجلىمىدە ئوتتۇراھال بولۇڭلار ۋە ئىسراپ قىلماڭلار. بارلىق مەخلۇقاتلارنىڭ ھوقۇقلىرىنى قوغداڭلار 6:141
- ئاللاھقا ھېچنىمىنى شېرىك كەلتۈرمەڭلار، ئاتا-ئانىغا ياخشىلىق قىلىڭلار، نامراتلىقتىن قورقۇپ بالىلىرىڭلارنى ئۆلتۈرمەڭلار، يامان ئىشلارغا يېقىنلاشماڭلار، ئاللاھ ھارام قىلغان ھېچقانداق جاننى ناھەق ئۆلتۈرمەڭلار. 6:151
- ئەمىن بولۇڭلار؛ ھېچقانداق سودىدا ئالدامچىلىق قىلماڭلار. يېتىمنىڭ مېلىغا يېقىنلاشماڭلار، پەقەت ئۇنى ياخشىلاش ئۈچۈنلا، ئۆلچەمنى تولۇق ۋە تارازىنى ئادىل تۇتۇڭلار، سۆزلىگەندە راست سۆزلەڭلار، ھەتتا يېقىن تۇغقان بولسىمۇ، ۋە ئاللاھنىڭ ئەھدىسىگە ۋەپا قىلىڭلار. 6:152
- تۈز يولغا ئەگىشىڭلار ۋە (باشقا) يوللارغا ئەگىشىپ كەتمەڭلار، چۈنكى ئۇلار سىلەرنى ئۇنىڭ يولىدىن ئايرىپ قويىدۇ. 6:153
- (ئى مۇھەممەد ﷺ) ئېيتقىن: "نامازىم، ئىبادەتلىرىم، ھاياتىم ۋە ئۆلۈمىم ئالەملەرنىڭ رەببى بولغان ئاللاھ ئۈچۈندۇر." 6:162
- كىبىرلىنمەڭلار 7:13
- شەيتان سىلەرنى ئالدىمىسۇن. 7:27
- (ئى مۇھەممەد ﷺ) ئېيتقىن: "رەببىم ئادىللىقنى بۇيۇردى..." 7:29
- بارلىق ئىشلاردا ئاللاھ بەلگىلىگەن چېگرىلارغا رىئايە قىلىڭلار. سۆز ۋە ھەرىكەتتە چېگرىدىن ئېشىپ كېتىشتىن ساقلىنىڭلار. يەڭلار ۋە ئىچىڭلار، ئەمما ئىسراپ قىلماڭلار. ناماز ۋاقتىدا پاكىز كىيىملەرنى كىيىڭلار 7:31
- ئاللاھ ئاسمانلارنى ۋە زېمىننى ئالتە كۈندە ياراتتى، ئاندىن ئەرشكە تەڭ كەلدى (ئۇنىڭ شانىغا لايىق ئۇسۇلدا). 7:54
- رەببىڭلارغا تەزەررۇ ۋە يوشۇرۇن ئىلتىجا قىلىڭلار. ئۇ چېگرىدىن ئاشقۇچىلارنى سۆيمەيدۇ. 7:55
- زېمىن ئىسلاھ قىلىنغاندىن كېيىن، ئۇ يەردە بۇزغۇنچىلىق قىلماڭلار ۋە ئۇنىڭغا قورقۇنچ ۋە ئۈمىد بىلەن ئىلتىجا قىلىڭلار. 7:56
- ئەمما يامان ئىشلارنى قىلىپ، ئاندىن كېيىن تەۋبە قىلىپ، ئىمان كەلتۈرگەنلەرگە، شۈبھىسىزكى، رەببىڭ شۇنىڭ ئارقىسىدىن بەك مەغپىرەت قىلغۇچى، بەك مېھرىباندۇر. 7:153
- (ئى مۇھەممەد ﷺ) ئېيتقىن: "ئى ئىنسانلار! مەن سىلەرنىڭ ھەممىڭلارغا ئاللاھنىڭ پەيغەمبىرىمەن..." 7:158
- ئەڭ گۈزەل ئىسىملەر ئاللاھنىڭدۇر، شۇڭا ئۇنى شۇ ئىسىملەر بىلەن چاقىرىڭلار ۋە ئۇنىڭ ئىسىملىرىنى بۇزىدىغانلارنى تاشلاپ قويۇڭلار... 7:180
- ئاللاھ كىمنى ئازدۇرسا، ئۇنىڭغا ھېچقانداق يېتەكچى يوق، ۋە ئۇ ئۇلارنى ئازغۇنچىلىقلىرىدا تېڭېرىتىپ قالدۇرىدۇ. 7:186
- كەچۈرۈشنى ئۆرپ قىلغىن، ياخشىلىققا بۇيرۇغىن ۋە جاهىللاردىن يۈز ئۆرۈگىن (يەنى ئۇلارغا جازا بەرمە). 7:199
- باشقىلارنىڭ خاتالىقلىرىنى كەچۈرۈڭلار 7:199
- ئەگەر ساڭا شەيتان تەرىپىدىن بىر ۋەسۋەسە كەلسە، ئاللاھقا سىغىن. شۈبھىسىزكى، ئۇ ھەممىنى ئاڭلىغۇچى، ھەممىنى بىلگۈچىدۇر. 7:200
- مۆمىنلەر پەقەت ئاللاھ ئېسىمى ئېيتىلغاندا قەلبلىرى قورقۇنچقا چۆمىدىغان، ئۇنىڭ ئايەتلىرى ئوقۇلغاندا ئىمانلىرى كۈچىيىدىغان كىشىلەردۇر... 8:2
- ئاللاھقا ۋە پەيغەمبىرىگە خىيانەت قىلماڭلار، ۋە بىلىپ تۇرۇپ ئامانەتلىرىڭلارغا (سىلەرگە تاپشۇرۇلغان نەرسىلەر ۋە ئاللاھ سىلەرگە بۇيرۇغان بارلىق ۋەزىپىلەرگە) خىيانەت قىلماڭلار. 8:27
- ئەگەر سىلەر ئاللاھقا ئىتائەت قىلساڭلار ۋە ئۇنىڭدىن قورقساڭلار، ئۇ سىلەرگە فۇرقاننى (ھەق-باتىلنى پەرق ئېتىش ئىقتىدارىنى) بېرىدۇ. 8:29
- كافىرلار ماللىرىنى (كىشىلەرنى) ئاللاھنىڭ يولىدىن توسۇش ئۈچۈن خەجلايدۇ، ۋە خەجلەيدۇ؛ ئەمما ئاخىرىدا بۇ ئۇلارغا ھەسرەت بولىدۇ. 8:36
- كافىرلارغا ئېيتقىنكى، ئەگەر ئۇلار (كۇفرىدىن) توختىسا، ئۆتكەن (گۇناھلىرى) كەچۈرۈلىدۇ. ئەگەر ئۇلار يەنە (كۇفرىغا) قايتسا، ئۇنداقتا ئالدىنقىلارنىڭ ئادىتى (ئوخشاش جازا) ئۆتكەن. 8:38
- سىلەر (دۈشمەن) قوشۇنى بىلەن ئۇچراشقاندا، ئۇلارغا قارشى تىك تۇرۇڭلار ۋە مۇۋەپپەقىيەت قازىنىش ئۈچۈن ئاللاھنىڭ ئىسمىنى كۆپ زىكر قىلىڭلار (تىل ۋە كۆڭۈل بىلەن). 8:45
- ئۆيلىرىدىن كىبىرلىنىپ، كىشىلەرگە كۆرسىتىش ئۈچۈن چىققان ۋە (كىشىلەرنى) ئاللاھنىڭ يولىدىن توسقانلارغا ئوخشىماڭلار. 8:47
- ئاللاھ بىر قەۋمگە بەرگەن نېمىتىنى، ئۇلار ئۆزلىرىنى ئۆزگەرتپىگىچە ئۆزگەرتەرمەيدۇ. 8:53
- ئاللاھنىڭ نەزىرىدە جانلىقلارنىڭ ئەڭ يامىنى كۇففارلاردۇر. 8:55
- ئاللاھ ئۇنىڭغا ئىمان كەلتۈرگەنلەرنىڭ قەلبلىرى ئارىسىغا مۇھەببەت ۋە مېھرىلىقنى سالىدۇ 8:63
- پاناھ تىلىگەنلەرنى قوغداڭلار ۋە ئۇلارغا ياردەم قىلىڭلار 9:6
- مۇشرىكلارنىڭ ئاللاھنىڭ مەسچىتلىرىنى ئىمارەت قىلىشىغا مۇناسىپ ئەمەس. 9:17
- ئۇلار (كافىرلار، يەھۇدىيلەر ۋە ناسارالار) ئاللاھنىڭ نۇرىنى (مۇھەممەد ﷺ ئەۋەتىلگەن ئىسلام تەۋھىدىنى) ئېغىزلىرى بىلەن ئۆچۈرمەكچى بولىدۇ، ئەمما كۇففارلار يامان كۆرسىمۇ، ئاللاھ ئۆز نۇرىنى مۇكەممەل قىلىشتىن باشقىغا يول قويمايدۇ. 9:32
- سەدىقە (زاكىت) پەقەت: 1) فۇقارالار، 2) مىسكىنلەر، 3) ئۇنى يىغىش بىلەن ۋەزىپىلەندۈرۈلگەنلەر، 4) كۆڭۈللىرى ئىسلامغا يېقىنلاشتۇرۇلغانلار، 5) قۇللارنى ئازاد قىلىش، 6) قەرزدارلار، 7) ئاللاھ يولىدا (جىھادچىلار) ۋە 8) يولۇچىلار ئۈچۈندۇر. 9:60
- كىم ئاللاھقا ۋە ئۇنىڭ پەيغەمبىرىگە (ﷺ) قارشى چىقسا ۋە دۈشمەنلىك قىلسا، ئۇنىڭغا دوزاخ ئوتى بولىدۇ، ئۇ يەردە مەڭگۈ قالىدۇ. بۇ كاتتا خارلىقتۇر. 9:63
- مۇناپىقلار، ئەر-ئايال، بىر-بىرىدىن. ئۇلار ئاللاھنى ئۇنتۇدى، ئاللاھمۇ ئۇلارنى ئۇنتۇدى. 9:67
- پاكلىق ئۈچۈن تىرىشىڭلار. مەسچىتنىڭ مۇقەددەسلىكىگە ھۆرمەت قىلىڭلار 9:108
- مۇشرىكلارنىڭ دوزاخلىق ئىكەنلىكى ئېنىق بولغاندىن كېيىن، پەيغەمبەر ۋە مۆمىنلەرگە ئۇلار تۇغقان بولسىمۇ (كۇفرىدا ئۆلگەنلىكى ئۈچۈن) ئۇلار ئۈچۈن مەغپىرەت تىلەش لايىق ئەمەس. 9:113
- ئاللاھقا يالغان چاپلاپ قويغان ياكى ئۇنىڭ ئايەتلىرىنى يالغانچىغا چىقارغان كىشىدىن زالىم كىم بار؟ شۈبھىسىزكى، گۇناھكارلار ھەرگىز مۇۋەپپەقىيەت قازانالمايدۇ! 10:17
- ئۇلار ئاللاھنى قويۇپ، ئۆزلىرىگە زىيان ياكى پايدا بېرەلمەيدىغان نەرسىلەرگە ئىبادەت قىلىدۇ ۋە: "بۇلار ئاللاھنىڭ دەرگاھىدىكى بىزنىڭ شاپائەتچىلىرىمىزدۇر" دەيدۇ. ئېيتقىن: "سىلەر ئاللاھقا ئاسمانلاردا ۋە يېرىمۇ يەردە بىلەلمەيدىغان نەرسىنى خەۋەر قىلىۋاتامسىلەر؟" ئۇلارنىڭ شېرىك كەلتۈرگەن نەرسىلىرىدىن ئاللاھ پاك ۋە يۇقىرىدۇر! 10:18
- يامانلىقنىڭ جازاسى ئوخشاش يامانلىقتۇر. 10:27
- ئاللاھ، سىلەرنىڭ ھەقىقىي رەببىڭلار شۇ. ھەقتىن قالسا ئازغۇنچىلىقتىن باشقا نېمە بار؟ قانداق ئېگىلىۋېلىسىلەر؟ 10:32
- ئۇلارنىڭ كۆپچىلىكى پەقەت گۇمانغا ئەگىشىدۇ، گۇمان ھەقنىڭ ئورنىنى ئالالمايدۇ. 10:36
- ئاللاھ كىشىلەرگە ھەرگىز زۇلۇم قىلمايدۇ، لېكىن كىشىلەر ئۆزلىرىگە زۇلۇم قىلىدۇ. 10:44
- ئاللاھنىڭ نېمىتى ئىنساننىڭ يىغىپ توپلىيالايدىغان ھەر نەرسىدىن ياخشى ئىكەنلىكىنى بىلىڭلار 10:58
- ئاللاھنىڭ ئايەتلىرىنى يالغانچىغا چىقارغۇچىلاردىن بولماڭلار، ئۇنداق بولسا زىيانكەشلەردىن بولۇپ قالىسىلەر. 10:95
- ئەگەر ئاللاھ ساڭا بىر زىيان يەتكۈزسە، ئۇنى ئۇنىڭدىن باشقا ھېچكىم كەتۈرەلمەيدۇ؛ ئەگەر ئۇ ساڭا ياخشىلىقنى خالىسا، ئۇنىڭ مەرھەمىتىنى ھېچكىم رەت قىلالمايدۇ، ئۇ ئۇنى بەندىلىرىدىن خالىغان كىشىگە يەتكۈزىدۇ. 10:107
- يېرىمۇ يەردە ھېچقانداق جانلىق يوقكى، ئۇنىڭ رىزقى ئاللاھقا تەۋە ئەمەس. ئۇنىڭ تۇرالغۇسىنى ۋە ساقلانغان جايىنى (قارىن، قەبرە ۋە باشقىلارنى) بىلىدۇ. 11:6
- ئەگەر بىز ئىنسانغا بىر رەھمەت تېتىتىپ، ئاندىن ئۇنى ئۇنىڭدىن تارتىۋالساق، ئۇ ئۈمىدسىز ۋە ناشۈكۈر بولۇپ قالىدۇ. 11:9
- كىم دۇنيا ھاياتى ۋە ئۇنىڭ زىننىتىنى خالىسا، بىز ئۇلارغا ئۇنىڭدا ئەجىرلىرىنى تولۇق بېرىمىز ۋە ئۇلارغا ھېچقانداق كەمچىلىك بولمايدۇ. 11:15
- بىز ئۇلارغا زۇلۇم قىلمىدۇق، لېكىن ئۇلار ئۆزلىرىگە زۇلۇم قىلدى. رەببىڭنىڭ ئەمرى كەلگەندە، ئۇلارنىڭ ئاللاھتىن باشقا ئىلتىجا قىلغان تەڭرىلىرى ئۇلارغا ھېچپايدىسىز بولۇپ قالدى ۋە ئۇلارغا ھالاكەتتىن باشقا نەرسىنى كۆپەيتمىدى. 11:101
- ئۇ (قىيامەت) كەلگەن كۈندە، ھېچكىم ئاللاھنىڭ ئىزنىسىز سۆزلىيەلمەيدۇ. ئۇلارنىڭ بەزىلىرى بەختسىز، (بەزىلىرى) بەختلىك بولىدۇ. 11:105
- بەختسىزلەرگە كەلسەك، ئۇلار دوزاختا بولۇپ، ئۇ يەردە ھۆڭرەيدۇ ۋە ئۆكۈرىدۇ. 11:106
- ئۇلار ئۇ يەردە رەببىڭ خالىغان ۋاقىتتىن باشقا، ئاسمانلار ۋە يېرىمۇ يەر تۇرغان مەزگىلچە مەڭگۈ قالىدۇ. رەببىڭ خالىغان ئىشىنى قىلغۇچىدۇر. 11:107
- بەختلىك بولغانلارغا كەلسەك، ئۇلار جەننەتتە بولۇپ، رەببىڭ خالىغان ۋاقىتتىن باشقا، ئاسمانلار ۋە يېرىمۇ يەر تۇرغان مەزگىلچە ئۇ يەردە مەڭگۈ قالىدۇ، بۇ تۈگىمەس نېمەتتۇر. 11:108
- زالىملارغا مەيلى قىلماڭلار، ئۇنداق بولسا دوزاخ سىلەرگە تەگسىن، ئاندىن ئاللاھتىن باشقا سىلەرگە ھېچقانداق دوست بولمايدۇ ۋە ياردەمگە ئېرىشەلمەيسىلەر. 11:113
- كۈندۈزنىڭ ئىككى تەرىپىدە ۋە كېچىنىڭ بەزى سائەتلىرىدە نامازنى ئوقۇڭلار (يەنى بەش ۋاقىت ناماز). ياخشى ئىشلار يامان ئىشلارنى (كىچىك گۇناھلارنى) يوقىتىدۇ. 11:114
- ئاسمانلار ۋە زېمىننىڭ غەيبى ئاللاھقا تەۋە، ھەممە ئىشلار ئۇنىڭغا (ھۆكۈم چىقىرىش ئۈچۈن) قايتۇرۇلىدۇ. 11:123
- ھۆكۈم ئاللاھتىن باشقا ھېچكىمنىڭ ئەمەس. ئۇ سىلەرگە ئۇنىڭدىن باشقا ھېچكىمگە ئىبادەت قىلماڭلار (تەۋھىد) دەپ بۇيۇردى، بۇ تۈز دىندۇر، لېكىن كىشىلەرنىڭ كۆپى بىلمەيدۇ. 12:40
- ئاللاھنىڭ رەھمىتىدىن ھەرگىز ئۈمىدسىزلىنىپ قالماڭلار 12:87
- سەن قانچىلىك قىزغىپ خالىسامۇ، كىشىلەرنىڭ كۆپى ئىمان كەلتۈرمەيدۇ. 12:103
- ئۇلارنىڭ كۆپى ئاللاھقا پەقەت شېرىك كەلتۈرگەن ھالدا (يەنى مۇشرىك بولۇپ) ئىمان كەلتۈرىدۇ. 12:106
- بۇ (قۇرئان) ئويدۇرما سۆز ئەمەس، بەلكى ئۇنىڭدىن ئالدىنقى كىتابلارنى (تەۋرات، ئىنجىل ۋە باشقا كىتابلارنى) تەستىقلىغۇچى ۋە ھەممە نەرسىنىڭ تەپسىلىي بايانى، ھەمدە ئىمان كەلتۈرگەن قەۋم ئۈچۈن ھىدايەت ۋە رەھمەتتۇر. 12:111
- ئاللاھ رىزىقنى خالىغان كىشىگە كەڭ قىلىدۇ ۋە (خالىغان كىشىگە) تار قىلىدۇ. 13:26
- ئاللاھنى زىكر ئارقىلىق كۆپ ئەسكە ئېلىڭلار. ئاللاھقا ئىمان كەلتۈرگەنلەر قەلبلىرى ئۇنىڭ زىكرى بىلەن تىنچلىق تېپىدۇ. 13:28
- ئىمان كەلتۈرگەن ۋە ياخشى ئىشلار قىلغانلارغا خۇشاللىق ۋە كۆڭۈل راھىتى بار. 13:29
- كىشىلەر ئاخىرەتتىن قالسا، دۇنيا ھاياتىنى ئارزۇ قىلىدىغان، (كىشىلەرنى) ئاللاھنىڭ يولىدىن (ئىسلامدىن) توسىدىغان ۋە ئۇنى بۇزۇشنى ئارزۇ قىلىدىغانلار، ئۇلار يىراق ئازغۇنچىلىقتىدۇر. 14:3
- ئىبادەتتە تەزەررۇ ۋە شۈكۈرنى ئۆرپ قىلىڭلار 14:7
- رەببىگە كۇفرى قىلغانلارنىڭ مىسالى: ئۇلارنىڭ قىلغان ئەمەللىرى كۈلگە ئوخشايدۇ، بورانلىق كۈندە شامال ئۇنىڭغا قاتتىق ئۇرسا، ئۇلار كەسپ قىلغان نەرسىلىرىدىن ھېچنەرسىگە قولى يەتمەيدۇ. 14:18
- ئاللاھ ئىمان كەلتۈرگەنلەرنى دۇنيادا (يەنى پەقەت ئاللاھقا ئىبادەت قىلىش) ۋە ئاخىرەتتە مۇستەھكەم سۆز بىلەن سابىت قىلىدۇ. 14:27
- ئاللاھ زالىملارنىڭ (مۇشرىكلارنىڭ، زۇلۇم قىلغۇچىلارنىڭ) قىلىۋاتقان ئىشلىرىدىن غاپىل دەپ ئويلىماڭلار، ئۇلارنى كۆزلەر قورقۇنچتىن تىكىلىپ قالىدىغان كۈنگە قالدۇرىدۇ. 14:42
- ئاللاھ ھەر بىر جانغا كەسپ قىلغىنىغا يارىشا جازا بېرىش ئۈچۈن. شۈبھىسىزكى، ئاللاھ ھېساب ئېلىشتا تېزدۇر. 14:51
- بىز ئىنساننى سادا چىقىدىغان قۇرۇق لايدىن، ئۆزگەرتىلگەن قارا پېچىنەتتىن ياراتتۇق. 15:26
- جىنلارنى بولسا ئۇنىڭدىن ئىلگىرى تۈتۈنسىز ئوتتىن ياراتتۇق. 15:27
- ئۇنىڭ (دوزاخنىڭ) يەتتە ئىشىكى بار؛ ھەر بىر ئىشىك ئۈچۈن (گۇناھكارلارنىڭ) ئالاھىدە بىر تۈركۈمى تەيىنلەنگەن. 15:44
- ئۇ ئىنساننى نۇتفىدىن (ئەر-ئايال جىنسىي سۇيۇقلۇقىنىڭ ئارىلاشما تەمچىسىدىن) ياراتتى، ئاندىن ئۇ ئوچۇق خىلاپچىغا ئايلىنىپ قالىدۇ. 16:4
- ھايۋانلارنى، ئۇ سىلەرگە ياراتتى؛ ئۇلاردا سىلەرگە ئىللىقلىق (ئىللىق كىيىملەر) ۋە نۇرغۇن پايدىلار بار، ئۇلارنى يەيسىلەر. 16:5
- ئات، خەچىر ۋە ئېشەكلەرنى (ياراتتى) سىلەر مىنىشىڭلار ۋە زىننەت ئۈچۈن. ۋە سىلەر بىلمەيدىغان نەرسىلەرنى يارىتىدۇ. 16:8
- ئۇ ئاسماندىن سۇ (يامغۇر) نى چۈشۈرگەن زاتتۇر؛ ئۇنىڭدىن ئىچىسىلەر ۋە ئۇنىڭدىن ئۆسۈملۈكلەر ئۆسىدۇ، ئۇنىڭدا ھايۋانلىرىڭلارنى ئوتلىتىسىلەر. 16:10
- ئۇ سىلەرگە دېڭىزنى بويسۇندۇرۇپ بەرگەن زاتتۇر، سىلەر ئۇنىڭدىن يېڭى گۆش (بېلىق) نى يەيسىلەر ۋە ئۇنىڭدىن كىيىدىغان زىننەت بۇيۇملىرىنى چىقىرىسىلەر. 16:14
- ئۇ زېمىندا تاغلارنى مۇستەھكەم قىلدى، سىلەرنى تەۋرەتمەسلىكى ئۈچۈن، ۋە ئۆستەڭلەر ۋە يوللارنى (قىلدى)، توغرا يېتەكلىنىشىڭلار ئۈچۈن. 16:15
- ياراتقان زات ھېچنەرسىنى يارىتالمايدىغان زات بىلەن ئوخشامدۇ؟ سىلەر ئويلىنىپ باقمايمسىلەر؟ 16:17
- ئەگەر سىلەر ئاللاھنىڭ نېمەتلىرىنى سانىساڭلار، سانىيالمايسىلەر. 16:18
- ئاللاھ سىلەرنىڭ يوشۇرغىنىڭلارنى ۋە ئاشكارىلىغىنىڭلارنى بىلىدۇ. 16:19
- ئۇلار (مۇشرىكلار) ئاللاھتىن باشقا ئىلتىجا قىلىدىغان بۇتلار ھېچنەرسىنى ياراتمىغان، بەلكى ئۇلار ئۆزلىرى يارىتىلغان. 16:20
- (ئۇلار) ئۆلۈك، جانسىز، ۋە قاچان تىرىلدۈرۈلىدىغانلىقىنى بىلمەيدۇ. 16:21
- بىز بىر نەرسىنى خالىغان ۋاقىتتا، ئۇنىڭغا سۆزىمىز پەقەت "بول!" دىيىشتىن ئىبارەت، ئۇ دەرھال بولۇپ قالىدۇ. 16:40
- يامان مىكر قىلىدىغانلار، ئاللاھ ئۇلارنى يېرىمۇ يەرگە باتۇرۇۋەتمەيدۇ دەپ ياكى ئۇلار خىيالىمۇ كەلتۈرەلمەيدىغان تەرەپتىن ئازاب كەلمەيدۇ دەپ بىخەتەر بولۇپ قالامدۇ؟ 16:45
- سىلەردە بار بولغان ھەر قانداق نېمەت ۋە ياخشىلىق ئاللاھتىندۇر. ئاندىن سىلەرگە بىر زىيان كەلگەندە، پەقەت ئۇنىڭغالا يالۋۇرىسىلەر. 16:53
- ئاندىن ئۇ زىياننى سىلەردىن كەتۈرگەندە، سىلەردىن بىر تۈركۈم رەببىگە شېرىك كەلتۈرۈپ قالىدۇ. 16:54
- ھايۋانلاردا سىلەرگە بىر ئىبرەت بار. بىز سىلەرنى ئۇلارنىڭ قارىنىدىكى نەرسىدىن، تەزەك ۋە قاننىڭ ئارىسىدىن، خالىس سۈت بىلەن سۇغىرىمىز، ئۇ ئىچكۈچىلەرگە تەتۈر بولىدۇ. 16:66
- شۇڭا ئاللاھقا ئوخشىتىشلارنى كەلتۈرمەڭلار (چۈنكى ئۇنىڭغا ئوخشايدىغان ھېچنەرسە يوق، ھەمدە ئۇ ھېچنەرسىگە ئوخشىمايدۇ). شۈبھىسىزكى، ئاللاھ بىلىدۇ، سىلەر بىلمەيسىلەر. 16:74
- بىلىڭلاركى، ئاللاھ ئىنسانغا ئاڭلاش، كۆرۈش، ئەقىل ۋە ھېسسىياتنى بەردى، شۈكۈر قىلىشلىرى ئۈچۈن 16:78
- ئاچكۆزلۈك ۋە ھەرىستىن ساقلىنىڭلار 16:97
- قۇرئان ئوقۇماقچى بولغىنىڭلاردا، قوغۇلغان شەيتاندىن ئاللاھقا سىغىنىڭلار. 16:98
- بىلىڭلاركى، بىلمەستىن قىلىنغان بىر زۇلۇم، ئەگەر كىشى تەۋبە قىلىپ ئۆزىنى تۈزىتىۋالسا كەچۈرۈلىدۇ 16:119
- (ئى مۇھەممەد ﷺ) رەببىڭنىڭ يولىغا (ئىسلامغا) ھىكمەت ۋە گۈزەل نەسىھەت بىلەن دەۋەت قىلغىن ۋە ئۇلار بىلەن ئەڭ گۈزەل ئۇسۇلدا مۇنازىرە قىلغىن. باشقىلارنى ئاللاھنىڭ يولىغا دەۋەت قىلىش ھىكمەت ۋە مېھرىبانلىق بىلەن بولۇشى كېرەك 16:125
- ئاللاھ تەقۋادارلار ۋە ياخشىلىق قىلغۇچىلار بىلەن بىللىدۇر. 16:128
- بۇ قۇرئان ئەڭ تۈز ۋە ئادىل بولغان نەرسىگە يېتەكچىلىك قىلىدۇ. 17:9
- ھېچكىم باشقىنىڭ گۇناھىنى كۆتۈرەلمەيدۇ. 17:15
- كىم ئاخىرەتنى خالىسا ۋە مۆمىن بولغان ھالدا ئۇنىڭغا لايىق تىرىشچانلىق كۆرسەتسە، ئۇلارنىڭ تىرىشچانلىقى مەقدۇرلىنىدۇ، مەنمۇن بولىدۇ ۋە (ئاللاھ تەرىپىدىن) ساۋاب بېرىلىدۇ. 17:19
- ئاتا-ئانىڭلارغا ھۆرمەت قىلىڭلار ۋە ئۇلارغا مېھرىبان بولۇڭلار. ئاتا-ئانىغا ياخشىلىق قىلىڭلار. ئۇلارغا قوپال سۆز دېمەڭلار. رەببىڭ سىلەرگە پەقەت ئۇنىڭغا ئىبادەت قىلىشنى ۋە ئاتا-ئانىغا ياخشىلىق قىلىشنى بۇيۇردى. ئەگەر ئۇلارنىڭ بىرى ياكى ھەر ئىككىسى سېنىڭ يېنىڭدا قېرىغان ۋاقىتتا، ئۇلارغا "ئۇف" دېمە، ئۇلارنىڭ ئۈستىگە بقراتما، ئۇلارغا ھۆرمەتلىك سۆز ئېيتقىن. 17:23
- ئۇلارغا مەرھەمەت بىلەن پەرۋىشكارلىق قانىتىنى يېيىپ قويغىن ۋە "رەببىم! ئۇلار مېنى كىچىك ۋاقتىمدا قانداق تەربىيىلىگەن بولسا، سەن ئۇلارغا رەھىم قىلغىن" دېگىن. 17:24
- شۈبھىسىزكى، ئىسراپچىلار شەيتانلارنىڭ ئىنىلىرىدۇر، شەيتان رەببىگە بەك ناشۈكۈردۇر. 17:27
- پۇلنى ئىسراپ قىلماڭلار 17:29
- نامراتلىقتىن قورقۇپ بالىلىرىڭلارنى ئۆلتۈرمەڭلار 17:31
- زىنا قىلماڭلار. نىكاھنىڭ مۇقەددەسلىكىنى ساقلاڭلار ۋە زىنادىن ساقلىنىڭلار 17:32
- ئۆلچىگەندە تولۇق ئۆلچەڭلار ۋە تۈز تارازىدا تارتىڭلار. بۇ ياخشىدۇر ۋە ئاقىبەتتىمۇ ياخشىدۇر. 17:35
- (ئى ئىنسان!) ئۆزىڭ بىلمەيدىغان نەرسىنىڭ ئارقىسىدىن يۈرمە (مەسىلەن كۆرمىگەن نەرسىنى "كۆردۈم" دېمە، ئاڭلىمىغان نەرسىنى "ئاڭلىدىم" دېمە). 17:36
- تەزەررۇ قىلغىن ۋە كىبىرلىنمە. زېمىندا كىبىرلىنىپ مەڭگۈ قىلما. سەن زېمىنىنى چاكالمايسەن ۋە تاغلارنىڭ ئېگىزلىكىگە يېتەلمەيسەن. 17:37
- رەببىڭ سېنى بەك ياخشى بىلىدۇ؛ خالىسا ساڭا رەھىم قىلىدۇ، ياكى خالىسا سېنى ئازابلايدۇ. 17:54
- كىم بۇ دۇنيادا كور بولسا (يەنى ئاللاھنىڭ ئايەتلىرىنى كۆرمەي، ئۇنىڭغا ئىمان كەلتۈرمەيدۇ)، ئۇ ئاخىرەتتىمۇ كور ۋە يولنى ئېڭىپ تېپىشتا تېخىمۇ ئازغۇندۇر. 17:72
- نامازنىڭ بەلگىلەنگەن ۋاقىتلىرىغا رىئايە قىلىڭلار 17:78
- بىز بۇ قۇرئاندا كىشىلەرگە ھەر تۈرلۈك مىساللارنى بايان قىلدۇق، ئەمما كىشىلەرنىڭ كۆپى پەقەت كۇفرىدىن باشقا (ھېچنەرسىنى) قوبۇل قىلىشتىن باش تارتىدۇ. 17:89
- بىز كىشىلەرگە بۇ قۇرئاندا ھەر تۈرلۈك مىساللارنى بەردۇق، لېكىن ئىنسان ھەممە نەرسىدىن كۆپ جىدەلچىدۇر. 18:54
